import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u01")
C = "B1-B2"
# Lições de aprofundamento (10–25): argumentação e debate.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)
def N(id, nl, pt, art, pl=None): return V(id, nl, pt, "noun", art, pl)

L(10, "Afirmar a tese com convicção", "Ik ben ervan overtuigd dat…",
  ["Formular uma tese clara com diferentes graus de convicção"],
  vocab=[X("v-ik-ben-van-mening","ik ben van mening dat…","sou da opinião de que…"), X("v-ik-ben-ervan-overtuigd","ik ben ervan overtuigd dat…","estou convencido de que…"),
         X("v-beargumenteren","beargumenteren","argumentar|fundamentar com argumentos","verb")],
  ex=[("Ik ben van mening dat we minder moeten vliegen.","Sou da opinião de que devemos voar menos."),("Ik ben ervan overtuigd dat dit plan werkt.","Estou convencido de que este plano funciona."),("Kun je dat beargumenteren?","Consegues fundamentar isso?")],
  review=["v-stelling","v-naar-mijn-mening","v-onderbouwen"],
  cefr=C, exs=[
    MA([("ik ben van mening dat…","sou da opinião de que…"),("ik ben ervan overtuigd dat…","estou convencido de que…"),("beargumenteren","fundamentar"),("stelling","tese")], "Tese.", ["v-ik-ben-van-mening","v-ik-ben-ervan-overtuigd","v-beargumenteren","v-stelling"]),
    MC("Ordene do MAIS forte: qual exprime mais convicção?", ["*Ik ben ervan overtuigd dat…","Ik denk dat…|Mais fraco.","Misschien…|Muito fraco."], "Graus.", ["v-ik-ben-ervan-overtuigd"]),
    TR("pt-nl","Sou da opinião de que devemos voar menos.", ["Ik ben van mening dat we minder moeten vliegen","Ik ben van mening dat wij minder moeten vliegen"], "Verbo no fim.", ["v-ik-ben-van-mening"]),
    TR("pt-nl","Estou convencido de que isto funciona.", ["Ik ben ervan overtuigd dat dit werkt","Ik ben er van overtuigd dat dit werkt"], "ervan overtuigd.", ["v-ik-ben-ervan-overtuigd"]),
    FB("Ik ben ___ overtuigd dat dit de beste oplossing is.", ["ervan"], "overtuigd van → ervan.", ["v-ik-ben-ervan-overtuigd"], choices=["ervan","erop","eraan"], tr="Estou convencido de que esta é a melhor solução."),
    MC("Qual é a ordem correta?", ["*Ik ben van mening dat we minder moeten vliegen.","Ik ben van mening dat we moeten minder vliegen.|Ordem: …dat we minder moeten vliegen."], "Ordem: …dat we minder moeten vliegen.", ["v-ik-ben-van-mening"]),
    DL([("Debatleider","Wat is uw standpunt over de vierdaagse werkweek?","Qual é a sua posição sobre a semana de quatro dias?"),("Jij","","")], ["*Ik ben van mening dat een vierdaagse werkweek goed is voor zowel werknemers als werkgevers.","Vierdaagse.|Incompleto.","Ik ben overtuigd.|Sem conteúdo."], "Abrir com tese.", ["v-ik-ben-van-mening","v-vierdaagse-werkweek"]),
    LI("Ik zal mijn standpunt met drie argumenten beargumenteren.", ["Ik zal mijn standpunt met drie argumenten beargumenteren","Ik zal mijn standpunt met 3 argumenten beargumenteren"], "Vou fundamentar a minha posição com três argumentos.", "Anunciar estrutura.", ["v-beargumenteren"]),
    WO("Estou convencido disso.", ["Ik","ben","ervan","overtuigd"], "Ordem.", ["v-ik-ben-ervan-overtuigd"]),
  ], diff=4, mins=5)

L(11, "Conceder e continuar", "Het is weliswaar duur, maar…",
  ["Reconhecer um ponto contrário e manter a posição"],
  vocab=[X("v-weliswaar","weliswaar","é certo que|embora","adverb"), X("v-niettemin","niettemin","no entanto|ainda assim","adverb"),
         N("v-tegenwerping","tegenwerping","objeção","de","tegenwerpingen")],
  ex=[("Het is weliswaar duur, maar het levert veel op.","É certo que é caro, mas compensa muito."),("Niettemin blijf ik bij mijn standpunt.","Ainda assim, mantenho a minha posição."),("Een veelgehoorde tegenwerping is dat het te veel kost.","Uma objeção frequente é que custa demasiado.")],
  review=["v-echter","v-desondanks","v-tegenargument"],
  cefr=C, exs=[
    MA([("weliswaar","é certo que"),("niettemin","ainda assim"),("tegenwerping","objeção"),("desondanks","apesar disso")], "Concessão.", ["v-weliswaar","v-niettemin","v-tegenwerping","v-desondanks"]),
    MC("«Weliswaar» anuncia quase sempre…", ["*um «maar» a seguir","uma conclusão|Não.","um exemplo|Não."], "Estrutura weliswaar … maar.", ["v-weliswaar"]),
    TR("pt-nl","É certo que é caro, mas compensa.", ["Het is weliswaar duur, maar het loont","Het is weliswaar duur, maar het levert veel op","Weliswaar is het duur, maar het loont"], "weliswaar … maar.", ["v-weliswaar"]),
    TR("pt-nl","Ainda assim, mantenho a minha posição.", ["Niettemin blijf ik bij mijn standpunt","Toch blijf ik bij mijn standpunt"], "Inversão.", ["v-niettemin"]),
    FB("Het plan is ___ ambitieus, maar het is haalbaar.", ["weliswaar"], "Concessão.", ["v-weliswaar"], choices=["weliswaar","niettemin","daardoor"], tr="O plano é, é certo, ambicioso, mas é exequível."),
    MC("Qual é a ordem correta?", ["*Niettemin blijf ik bij mijn standpunt.","Niettemin ik blijf bij mijn standpunt.|Inversão: Niettemin blijf ik."], "Inversão: Niettemin blijf ik.", ["v-niettemin"]),
    DL([("Tegenstander","Maar dat kost de gemeente miljoenen!","Mas isso custa milhões à câmara!"),("Jij","","")], ["*Dat klopt weliswaar, maar op lange termijn besparen we juist geld.","Nee.|Sem argumento.","Niettemin.|Incompleto."], "Conceder e responder.", ["v-weliswaar"]),
    AR("tegenwerping", "objeção", "de", "-ing → de.", ["v-tegenwerping"]),
    LI("Een begrijpelijke tegenwerping, maar niettemin onjuist.", ["Een begrijpelijke tegenwerping, maar niettemin onjuist","Een begrijpelijke tegenwerping maar niettemin onjuist"], "Uma objeção compreensível, mas ainda assim incorreta.", "Responder.", ["v-tegenwerping","v-niettemin"]),
  ], diff=4, mins=5)

L(12, "Pesar prós e contras", "De prijs gaf de doorslag.",
  ["Comparar vantagens e desvantagens e dizer o que decide"],
  vocab=[X("v-voor-en-nadelen","de voor- en nadelen","os prós e contras"), X("v-de-doorslag-geven","de doorslag geven","ser decisivo"),
         X("v-doorslaggevend","doorslaggevend","decisivo","adjective")],
  ex=[("Laten we de voor- en nadelen op een rij zetten.","Vamos pôr os prós e contras lado a lado."),("Uiteindelijk gaf de prijs de doorslag.","No fim, o preço foi decisivo."),("Veiligheid is voor mij doorslaggevend.","Para mim a segurança é decisiva.")],
  review=["v-afwegen","v-aan-de-ene-kant"],
  cefr=C, exs=[
    MA([("de voor- en nadelen","prós e contras"),("de doorslag geven","ser decisivo"),("doorslaggevend","decisivo"),("afwegen","ponderar")], "Ponderar.", ["v-voor-en-nadelen","v-de-doorslag-geven","v-doorslaggevend","v-afwegen"]),
    TR("pt-nl","No fim, o preço foi decisivo.", ["Uiteindelijk gaf de prijs de doorslag","Uiteindelijk was de prijs doorslaggevend"], "de doorslag geven.", ["v-de-doorslag-geven"]),
    TR("pt-nl","Vamos ponderar os prós e contras.", ["Laten we de voor- en nadelen afwegen","Laten we de voor en nadelen afwegen"], "afwegen.", ["v-voor-en-nadelen"]),
    MC("«Wat gaf voor jou de doorslag?» pergunta…", ["*qual foi o fator decisivo","quem ganhou|Não.","quanto custou|Não."], "Pergunta.", ["v-de-doorslag-geven"]),
    FB("De locatie was ___ voor onze keuze.", ["doorslaggevend"], "Adjetivo.", ["v-doorslaggevend"], choices=["doorslaggevend","doorslag","weliswaar"], tr="A localização foi decisiva para a nossa escolha."),
    MC("Qual é a ordem correta?", ["*Uiteindelijk gaf de prijs de doorslag.","Uiteindelijk de prijs gaf de doorslag.|Inversão: Uiteindelijk gaf de prijs…"], "Inversão: Uiteindelijk gaf de prijs…", ["v-de-doorslag-geven"]),
    CO("text","Huren of kopen?","Kopen heeft voordelen: je bouwt vermogen op en je mag je huis verbouwen zoals je wilt. Aan de andere kant heb je bij kopen een hoge aanbetaling nodig en ben je zelf verantwoordelijk voor onderhoud. Huren is flexibeler. Voor Sara gaf de flexibiliteit de doorslag: ze weet nog niet of ze in Nederland blijft.",
       [("Vantagem de comprar?", ["*Constrói património","É mais flexível","Não há manutenção"]),("Desvantagem de comprar?", ["*Entrada alta","Não se pode remodelar","Renda alta"]),("O que decidiu para a Sara?", ["*A flexibilidade","O preço","A localização"])],
       "Ponderar.", ["v-voor-en-nadelen","v-de-doorslag-geven"]),
    SW("Escreva 4–5 frases a pesar os prós e contras de uma decisão sua (por ex. carro ou bicicleta, cidade ou aldeia). Diga o que foi decisivo.", ["Ik twijfelde tussen een auto en een e-bike. Een auto is comfortabel, maar duur. Een e-bike is goedkoper en gezonder, maar in de regen minder fijn. Uiteindelijk gaf de prijs de doorslag: ik koos de e-bike."], ["Prós","Contras","de doorslag geven"], 30, "Decisão.", ["v-voor-en-nadelen","v-de-doorslag-geven"]),
    WO("O preço foi decisivo.", ["De","prijs","gaf","de","doorslag"], "Ordem.", ["v-de-doorslag-geven"]),
  ], diff=4, mins=6)

L(13, "Simplificar demais", "Dat is wel erg kort door de bocht.",
  ["Criticar simplificações e pedir nuance"],
  vocab=[X("v-kort-door-de-bocht","kort door de bocht","simplista|apressado"), X("v-zwart-wit","zwart-wit denken","pensar a preto e branco"),
         N("v-nuance","nuance","nuance","de","nuances")],
  ex=[("Dat is wel erg kort door de bocht.","Isso é bastante simplista."),("Je moet niet zo zwart-wit denken.","Não deves pensar tanto a preto e branco."),("Ik wil graag een nuance aanbrengen.","Gostaria de acrescentar uma nuance.")],
  review=["v-generalisatie"],
  cefr=C, exs=[
    MA([("kort door de bocht","simplista"),("zwart-wit denken","pensar a preto e branco"),("nuance","nuance"),("nuanceren","matizar")], "Nuance.", ["v-kort-door-de-bocht","v-zwart-wit","v-nuance"]),
    MC("«Alle jongeren zitten alleen maar op hun telefoon.» Resposta adequada:", ["*Dat is wel erg kort door de bocht; veel jongeren doen ook vrijwilligerswerk.","Ja, altijd.|Aceita a generalização.","Jongeren zijn zwart-wit.|Sem sentido."], "Criticar.", ["v-kort-door-de-bocht"]),
    TR("pt-nl","Isso é bastante simplista.", ["Dat is wel erg kort door de bocht","Dat is erg kort door de bocht","Dat is nogal kort door de bocht"], "Expressão.", ["v-kort-door-de-bocht"]),
    TR("pt-nl","Gostaria de acrescentar uma nuance.", ["Ik wil graag een nuance aanbrengen","Ik zou graag een nuance willen aanbrengen"], "een nuance aanbrengen.", ["v-nuance"]),
    FB("Het is niet zo ___: er zijn ook grijze gebieden.", ["zwart-wit"], "Expressão.", ["v-zwart-wit"], choices=["zwart-wit","kort","doorslaggevend"], tr="Não é tão preto e branco: também há zonas cinzentas."),
    FE(["Ik","wil","graag","een","nuance","aanbrengt."], 5, "aanbrengen", "Depois de wil: infinitivo.", ["v-nuance"]),
    EX("kort door de bocht", "curto pela curva", "O que significa?", ["*simplista, sem nuance","rápido e eficiente|Não.","uma estrada perigosa|Literal."], "Imagem: cortar a curva.", ["v-kort-door-de-bocht"]),
    LI("Volgens mij is de werkelijkheid iets genuanceerder.", ["Volgens mij is de werkelijkheid iets genuanceerder"], "Na minha opinião a realidade é um pouco mais matizada.", "Pedir nuance.", []),
    WO("Não penses tão a preto e branco.", ["Denk","niet","zo","zwart-wit"], "Imperativo.", ["v-zwart-wit"]),
  ], diff=4, mins=5)

L(14, "Falácias: círculo e espantalho", "Dat is een cirkelredenering.",
  ["Reconhecer o raciocínio circular e o argumento do espantalho"],
  vocab=[N("v-cirkelredenering","cirkelredenering","raciocínio circular","de"), N("v-stropop","stropopredenering","argumento do espantalho","de"),
         N("v-aanname","aanname","pressuposto","de","aannames")],
  ex=[("«Het is waar, omdat het zo is» is een cirkelredenering.","«É verdade porque é assim» é um raciocínio circular."),("Dat heb ik niet gezegd; dat is een stropopredenering.","Eu não disse isso; isso é o argumento do espantalho."),("Je argument berust op een verkeerde aanname.","O teu argumento assenta num pressuposto errado.")],
  review=["v-drogreden","v-redenering"],
  gram=[G("g-drogredenen1","Duas falácias comuns","**Cirkelredenering**: a conclusão já está na premissa (*Dit boek is betrouwbaar, want het staat in dit boek.*). **Stropopredenering**: deformar o argumento do outro para o atacar mais facilmente (*Jij wilt minder auto's? Dus jij wilt dat niemand meer naar zijn werk kan!*).",
    [("Dat zeg ik helemaal niet.","Eu não digo nada disso."),("Je verdraait mijn woorden.","Estás a distorcer as minhas palavras.")])],
  cefr=C, exs=[
    MA([("cirkelredenering","raciocínio circular"),("stropopredenering","argumento do espantalho"),("aanname","pressuposto"),("drogreden","falácia")], "Falácias.", ["v-cirkelredenering","v-stropop","v-aanname","v-drogreden"]),
    MC("«Ik heb gelijk, want ik zeg altijd de waarheid, en dat is waar omdat ik het zeg.»", ["*cirkelredenering","stropopredenering|Não deforma o outro.","een goed argument|Não."], "Circular.", ["v-cirkelredenering"]),
    MC("A: «We moeten iets minder vlees eten.» B: «Dus jij wilt alle boeren werkloos maken!»", ["*stropopredenering","cirkelredenering|Não.","een nuance|Não."], "Deformação.", ["v-stropop"]),
    TR("pt-nl","Eu não disse isso.", ["Dat heb ik niet gezegd","Dat zei ik niet"], "Defender-se.", ["v-stropop"]),
    TR("pt-nl","O teu argumento assenta num pressuposto errado.", ["Je argument berust op een verkeerde aanname","Jouw argument berust op een verkeerde aanname","Je argument is gebaseerd op een verkeerde aanname"], "berusten op.", ["v-aanname"]),
    FB("Je argument berust op een ___ die niet klopt.", ["aanname"], "Pressuposto.", ["v-aanname"], choices=["aanname","stropop","nuance"], tr="O teu argumento assenta num pressuposto que não está certo."),
    FE(["Dat","is","een","typische","cirkelredeneringen."], 4, "cirkelredenering.", "Singular.", ["v-cirkelredenering"]),
    LI("Je verdraait mijn woorden.", ["Je verdraait mijn woorden"], "Estás a distorcer as minhas palavras.", "Defesa.", ["v-stropop"]),
    DL([("Tegenstander","Dus jij vindt dat niemand meer mag autorijden?","Então achas que ninguém pode andar de carro?"),("Jij","","")], ["*Dat heb ik niet gezegd. Ik pleit alleen voor minder auto's in het centrum.","Ja, niemand!|Aceita o espantalho.","Cirkel.|Incompleto."], "Desmontar o espantalho.", ["v-stropop"]),
  ], diff=5, mins=6)

